"""
AI Context

This module defines the shared context that is passed to every AI agent.
Each agent can read from this context but should not modify it directly.
"""

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional


@dataclass
class AIContext:
    """
    Shared context for all AI agents.
    """

    # Stock symbol
    symbol: str

    # Trade generated by Strategy Engine
    trade: Any

    # Trade quality score from Commit 19
    trade_score: float

    # Complete scoring breakdown
    score_breakdown: Dict[str, float] = field(default_factory=dict)

    # Historical market data
    market_data: Any = None

    # Portfolio information
    portfolio: Optional[Any] = None

    # Current market information
    market_state: Dict[str, Any] = field(default_factory=dict)

    # Extra metadata
    metadata: Dict[str, Any] = field(default_factory=dict)

    # Messages exchanged between AI agents
    agent_messages: List[Dict[str, Any]] = field(default_factory=list)

    def add_message(
        self,
        agent: str,
        message: str,
        confidence: Optional[float] = None
    ) -> None:
        """
        Add a message produced by an AI agent.
        """

        self.agent_messages.append({
            "agent": agent,
            "message": message,
            "confidence": confidence
        })

    def get_messages(self) -> List[Dict[str, Any]]:
        """
        Return all AI agent messages.
        """

        return self.agent_messages